/// <summary>One record of <see cref="GameState.Units"/>: page 1, <c>52</c> slots per field from offset 0; the script selects it with <c>Unit_Cur</c>.</summary>
public sealed class UnitRecord(ScriptMemory memory, int index) : IRecord<UnitRecord>
{
    /// <inheritdoc />
    public static UnitRecord Create(ScriptMemory memory, int index) => new(memory, index);

    /// <summary>The cursor value that selects this record.</summary>
    public int Index => index;

    /// <summary>VAR0074 [C] — Current troop count of the unit; prologue +2/week, later + rnd(1..2*Recovery)+Recovery weekly, capped at max.</summary>
    public Sys3Int Troops
    {
        get => memory.ReadPage(1, 0 + index);
        set => memory.WritePage(1, 0 + index, value);
    }

    /// <summary>VAR0075 [C] — Maximum troop count (shown as Max); raised by Add New Troops; 0 = commander without troops.</summary>
    public Sys3Int MaxTroops
    {
        get => memory.ReadPage(1, 52 + index);
        set => memory.WritePage(1, 52 + index, value);
    }

    /// <summary>VAR0076 [C] — Troop attack, fixed per troop type (Thieves 6, Soldiers 8, Knights 10, Mages 3); item effect 3 adds to it.</summary>
    public Sys3Int TroopAtk
    {
        get => memory.ReadPage(1, 104 + index);
        set => memory.WritePage(1, 104 + index, value);
    }

    /// <summary>VAR0077 [C] — Troop defense, fixed per troop type.</summary>
    public Sys3Int TroopDef
    {
        get => memory.ReadPage(1, 156 + index);
        set => memory.WritePage(1, 156 + index, value);
    }

    /// <summary>VAR0084 [C] — Troop attack modifier active in the current battle, copied from 0078/0080/0082 by situation VAR0581 (1 offense, 2 defense, 3 dungeon); 0-9 = +n, 10 = none, 11-19 = -(n-10); applied only to player troop attack (troops vs commander, troops vs troops).</summary>
    public Sys3Int CurAtkMod
    {
        get => memory.ReadPage(1, 208 + index);
        set => memory.WritePage(1, 208 + index, value);
    }

    /// <summary>VAR0085 [C] — Troop defense modifier active in the current battle, copied from 0079/0081/0083 by VAR0581; 0-9 = +n, 10 = none, 11-19 = -(n-10); applied only to player troop defense against enemy troops and enemy commanders' physical attacks.</summary>
    public Sys3Int CurDefMod
    {
        get => memory.ReadPage(1, 260 + index);
        set => memory.WritePage(1, 260 + index, value);
    }

    /// <summary>VAR0086 [C] — Troop class: 0 Assault, 1 Archers, 2 Mages, 3 Magic Warriors, 4 Phantom Beasts, 10 Demon Assault, 11 Demon Magic; &gt;=10 = demon (HP immune to non-demons unless attacker holds Chaos/Nikkou).</summary>
    public Sys3Int Class
    {
        get => memory.ReadPage(1, 312 + index);
        set => memory.WritePage(1, 312 + index, value);
    }

    /// <summary>VAR0099 [C] — Weekly troop replenishment base: troops += rnd(1..2n) + n; +1 each time new troops are bought.</summary>
    public Sys3Int Recovery
    {
        get => memory.ReadPage(1, 364 + index);
        set => memory.WritePage(1, 364 + index, value);
    }

    /// <summary>VAR0100 [C] — Base war expense to deploy (x100K GOLD); total = n + troops/300.</summary>
    public Sys3Int DeployCost
    {
        get => memory.ReadPage(1, 416 + index);
        set => memory.WritePage(1, 416 + index, value);
    }

    /// <summary>VAR0087 [C] — Commander attack; item effect 1 adds to it.</summary>
    public Sys3Int Atk
    {
        get => memory.ReadPage(1, 468 + index);
        set => memory.WritePage(1, 468 + index, value);
    }

    /// <summary>VAR0088 [C] — Commander defense; item effect 2 adds to it.</summary>
    public Sys3Int Def
    {
        get => memory.ReadPage(1, 520 + index);
        set => memory.WritePage(1, 520 + index, value);
    }

    /// <summary>VAR0089 [C] — Number of attacks; commander-vs-troops shots = rnd(n) + n/2; commander-vs-commander shots = rnd(n/5) (0 -&gt; 1, &gt;5 -&gt; rnd(6)); +1 per level-up.</summary>
    public Sys3Int Attacks
    {
        get => memory.ReadPage(1, 572 + index);
        set => memory.WritePage(1, 572 + index, value);
    }

    /// <summary>VAR0090 [C] — Commander HP; reaching 0 in battle sets Unit_Status = 0 (defeated).</summary>
    public Sys3Int HP
    {
        get => memory.ReadPage(1, 624 + index);
        set => memory.WritePage(1, 624 + index, value);
    }

    /// <summary>VAR0091 [C] — Commander max HP; HP refills to it weekly in the prologue, +2/week afterwards.</summary>
    public Sys3Int MaxHP
    {
        get => memory.ReadPage(1, 676 + index);
        set => memory.WritePage(1, 676 + index, value);
    }

    /// <summary>VAR0092 [C] — Successful strategy chance in percent; item effect 6 adds to it.</summary>
    public Sys3Int Strategy
    {
        get => memory.ReadPage(1, 728 + index);
        set => memory.WritePage(1, 728 + index, value);
    }

    /// <summary>VAR0093 [C] — Magic attack/defense value; item effects 5 (attack) and 8 (magic defense) add to it.</summary>
    public Sys3Int Magic
    {
        get => memory.ReadPage(1, 780 + index);
        set => memory.WritePage(1, 780 + index, value);
    }

    /// <summary>VAR0101 [C] — Equipped item index (Item_Cur), 0 = none; item 48 drains troops and item 50 adds troops weekly.</summary>
    public Sys3Int Item
    {
        get => memory.ReadPage(1, 832 + index);
        set => memory.WritePage(1, 832 + index, value);
    }

    /// <summary>VAR0082 [C] — Situational troop attack modifier in dungeons (same encoding).</summary>
    public Sys3Int DgnAtkMod
    {
        get => memory.ReadPage(1, 884 + index);
        set => memory.WritePage(1, 884 + index, value);
    }

    /// <summary>VAR0083 [C] — Situational troop defense modifier in dungeons (same encoding).</summary>
    public Sys3Int DgnDefMod
    {
        get => memory.ReadPage(1, 936 + index);
        set => memory.WritePage(1, 936 + index, value);
    }

    /// <summary>VAR0102 [C] — 0 = not in army (absent or defeated), 1 = ready, 2 = deployed this week (greyed; reset to 1 at week start).</summary>
    public Sys3Int Status
    {
        get => memory.ReadPage(1, 988 + index);
        set => memory.WritePage(1, 988 + index, value);
    }

    /// <summary>VAR0103 [C] — Partner unit index; when the partner is in a battle slot: 'Surging with power', rnd(3) gives +2/+1/+0 to player troop attack and troop defense rolls (not to the commander).</summary>
    public Sys3Int Partner
    {
        get => memory.ReadPage(1, 1040 + index);
